(function(E){ const x = E["int-m3"] = E["int-m3"] || {units:{}}; x.units["int-7"] = {"grammar":{"id":"c-int-7-g","level":"B1","course":"interview","unit":"int-7","title":"Asking good questions: do, does, is, are","titleTr":"İyi sorular sormak: do, does, is, are","titleFa":"سؤال خوب پرسیدن: do، does، is، are","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["What / How + do + I / you / they + verb","What do new staff do in the first week?"],["What / How + does + he / she / it + verb (no -s)","How does the team measure success?"],["With be: is / are first","What are the next steps?"]]},"wrong":"How the team plans its work each week?","right":"How does the team plan its work each week?","blank":{"sentence":"What ___ a typical day look like for a new nurse?","word":"does","distractors":["is","do"]},"wrong2":"What does the training includes?","right2":"What does the training include?","blank2":{"sentence":"What ___ the biggest challenges for the new team?","word":"are","distractors":["do","does"]},"expParts":{"rule":[{"en":"Most verbs: question word + do / does + subject + verb.","tr":"Çoğu fiil: soru kelimesi + do / does + özne + fiil.","fa":"برای بیشتر فعل‌ها اول کلمه‌ی پرسشی می‌آید، بعد do یا does، بعد فاعل و بعد فعل.","ex":"What do new staff do in the first week?"},{"en":"After does, the verb has no -s, because does already has it.","tr":"does kelimesinden sonra fiil -s almaz, çünkü -s zaten does içinde vardır.","fa":"بعد از does فعل ‎-s نمی‌گیرد، چون خود does آن را دارد.","ex":"How does the team measure success?"},{"en":"With be, there is no do or does: is or are comes first.","tr":"be ile do ya da does kullanılmaz: is ya da are başa gelir.","fa":"با be دیگر do یا does نمی‌آید: is یا are اول می‌آید.","ex":"What are the next steps?"}],"test":{"en":"Is there a helper verb right after the question word? If not, add do or does.","tr":"Soru kelimesinden hemen sonra bir yardımcı fiil var mı? Yoksa do ya da does ekle.","fa":"درست بعد از کلمه‌ی پرسشی فعل کمکی هست؟ اگر نیست، do یا does اضافه کن."},"contrast":{"en":"Turkish asks with -mı or a question word and Persian with tone or 'آیا', and the word order stays the same. English needs a helper verb in front: do, does, is, are.","tr":"Türkçede soru '-mı' ekiyle ya da soru kelimesiyle kurulur ve sıra değişmez. İngilizcede öne bir yardımcı fiil gelir: do, does, is, are.","fa":"در فارسی سؤال را با لحن یا «آیا» می‌سازیم و ترتیب کلمه‌ها عوض نمی‌شود. انگلیسی یک فعل کمکی جلوی جمله می‌خواهد: do، does، is، are."}},"errorWatch":[{"find":["does the training includes","does the team plans","does the job includes","does the team measures","does it takes","does she works","does he works","does the company trains","does the role involves"],"fix":{"en":"After does, the verb has no -s: 'What does the training include?'","tr":"does'tan sonra fiil -s almaz: 'What does the training include?'","fa":"بعد از does فعل s نمی‌گیرد: «What does the training include?‎»"}}]},"b2":{"id":"c-int-7-b2","level":"B2","track":"B2","course":"interview","unit":"int-7","title":"Softer questions: indirect questions","titleTr":"Daha yumuşak sorular: dolaylı sorular","titleFa":"سؤال‌های نرم‌تر: سؤال غیرمستقیم","formsTable":{"headers":{"en":["Direct","Indirect"],"tr":["Doğrudan","Dolaylı"],"fa":["مستقیم","غیرمستقیم"]},"rows":[["What are the next steps?","Could you tell me what the next steps are?"],["How does the team measure success?","I was wondering how the team measures success."],["When does the training start?","Do you know when the training starts?"]]},"wrong":"Could you tell me what are the next steps?","right":"Could you tell me what the next steps are?","blank":{"sentence":"I was wondering how often ___ with a trainer.","word":"new staff work","distractors":["do new staff work","work new staff"]},"wrong2":"I was wondering how does the company choose its suppliers.","right2":"I was wondering how the company chooses its suppliers.","blank2":{"sentence":"Could you tell me when ___?","word":"the training starts","distractors":["does the training start","starts the training"]},"useIn":{"en":"B2: make one of your three questions indirect (Could you tell me... / I was wondering...).","tr":"B2: üç sorundan birini dolaylı yap (Could you tell me... / I was wondering...).","fa":"در مسیر B2: یکی از سه سؤالت را غیرمستقیم کن (Could you tell me... / I was wondering...)."},"exitItem":{"from":"int-7","kind":"blank","prompt":"Could you tell me who ___ to in the first month?","options":["I would report","would I report","I would to report"],"correct":0,"why":{"en":"I would report: inside 'Could you tell me who...', use statement order. 'Would I report' is question order, and 'would to report' is wrong.","tr":"I would report: 'Could you tell me who...' içinde düz cümle sırası kullanılır. 'Would I report' soru sırasıdır; 'would to report' yanlıştır.","fa":"I would report درست است، چون بعد از Could you tell me who ترتیب جمله‌ی خبری می‌آید. would I report ترتیب سؤالی است و would to report غلط است."}},"expParts":{"rule":[{"en":"A polite opener, then statement order.","tr":"Kibar bir giriş, sonra düz cümle sırası.","fa":"با یک عبارت مؤدبانه شروع کن و بعد ترتیب جمله‌ی خبری بیاور.","ex":"Could you tell me what the next steps are?"},{"en":"No do or does after the opener.","tr":"Girişten sonra do ya da does yok.","fa":"بعد از این عبارت مؤدبانه do یا does نمی‌آید.","ex":"I was wondering how the team measures success."},{"en":"Mix one or two with direct questions.","tr":"Bir ikisini doğrudan sorularla karıştır.","fa":"یکی دو سؤال این‌طوری را کنار سؤال‌های مستقیم بپرس.","ex":"What does the first week look like?"}],"test":{"en":"Cover the opener. Does the rest sound like a normal sentence? Then it is right.","tr":"Giriş kalıbını kapat. Geri kalanı normal bir cümle gibi mi? O zaman doğru.","fa":"عبارت اول را بپوشان. بقیه مثل یک جمله‌ی معمولی است؟ پس درست است."},"contrast":{"en":"Turkish 'Sonraki adımların ne olduğunu söyler misiniz?' and Persian 'می‌شود بگویید قدم بعدی چیست؟' still feel like questions, so learners keep question order. In English, after the opener, the order goes back to a statement.","tr":"Türkçedeki 'Sonraki adımların ne olduğunu söyler misiniz?' hâlâ bir soru gibi hissettirir, bu yüzden soru sırasını koruruz. İngilizcede girişten sonra sıra düz cümleye döner: what the next steps are.","fa":"در فارسی «می‌شود بگویید قدم بعدی چیست؟» هنوز حس سؤال دارد و برای همین ترتیب سؤالی را نگه می‌داریم. در انگلیسی بعد از عبارت مؤدبانه، ترتیب جمله خبری می‌شود: what the next steps are."}},"errorWatch":[{"find":["tell me what are","tell me when does","tell me how does","tell me what does","wondering how does","wondering what does","wondering when does","wondering what are","tell me who will i","tell me when is the"],"fix":{"en":"After 'Could you tell me' or 'I was wondering', use statement order: 'Could you tell me what the next steps are?'","tr":"'Could you tell me' ya da 'I was wondering'den sonra düz cümle sırası kullan: 'Could you tell me what the next steps are?'","fa":"بعد از «Could you tell me» یا «I was wondering» ترتیب جمله‌ی خبری بیاور: «Could you tell me what the next steps are?‎»"}}]},"vocab":{"id":"c-int-7-v","level":"B1","category":"vocab","course":"interview","unit":"int-7","goals":["career"],"title":{"en":"Questions for Them","tr":"Onlara Sorular","fa":"سؤال‌هایی برای آن‌ها"},"cards":[{"word":"typical day","sentence":"What does a typical day look like in this job?","meaning":{"en":"A normal, usual day.","tr":"sıradan bir gün, tipik bir gün.","fa":"یک روز معمولی"}},{"word":"team","sentence":"How big is the team I would join?","meaning":{"en":"A group of people who work together.","tr":"ekip.","fa":"تیم"}},{"word":"training","sentence":"What training do new staff get in the first month?","meaning":{"en":"Teaching people the skills for a job.","tr":"eğitim.","fa":"آموزش"}},{"word":"next steps","sentence":"What are the next steps after this interview?","meaning":{"en":"What will happen next in the process.","tr":"sonraki adımlar.","fa":"مراحل بعدی"}},{"word":"success","sentence":"How do you measure success in this role?","meaning":{"en":"Doing well; getting the result you want.","tr":"başarı.","fa":"موفقیت"}},{"word":"report to","sentence":"Who would I report to?","meaning":{"en":"To have someone as your manager.","tr":"(birine) bağlı çalışmak.","fa":"زیر نظرِ کسی کار کردن"}},{"word":"opportunity","sentence":"Are there opportunities to grow in the company?","meaning":{"en":"A chance to do something good.","tr":"fırsat.","fa":"فرصت"},"gap":"opportunities","accept":["opportunities"]},{"word":"culture","sentence":"How would you describe the culture of the team?","meaning":{"en":"The way people in a group usually work and behave.","tr":"kültür, çalışma ortamı.","fa":"فرهنگ؛ فضای کاری"}},{"word":"research","sentence":"I did some research on your new branch before today.","meaning":{"en":"Finding information about something.","tr":"araştırma.","fa":"تحقیق؛ پژوهش"}},{"word":"look forward to","sentence":"I look forward to hearing from you.","meaning":{"en":"To feel happy about something that will happen.","tr":"dört gözle beklemek.","fa":"مشتاقانه منتظرِ چیزی بودن"}}]},"judge":{"id":"c-int-7-j","course":"interview","unit":"int-7","type":"judge","title":{"en":"Good questions to ask","tr":"Sorulacak iyi sorular","fa":"سؤال‌های خوب برای پرسیدن"},"prompt":"The interviewer says: \"Do you have any questions for us?\" Five candidates answer.","parts":["About the real work","Shows I did research","Helps me decide"],"instruction":{"en":"Tap what each question does. The strongest question does all three.","tr":"Her sorunun ne yaptığına dokun. En güçlü soru üçünü de yapar.","fa":"روی کاری که هر سؤال می‌کند بزن. قوی‌ترین سؤال هر سه را انجام می‌دهد."},"items":[{"by":"Accountant","answer":"No, I think you explained everything. Thank you.","present":[],"fix":{"en":"It sounds polite, but it can look like low interest. Always bring three questions.","tr":"Kibar duruyor, ama ilgisizlik gibi görünebilir. Her zaman üç soruyla gel.","fa":"مؤدبانه است، ولی ممکن است فکر کنند علاقه‌ای نداری. همیشه سه سؤال همراهت داشته باش."}},{"by":"Graduate","answer":"How much holiday will I get, and when do I get a pay rise?","present":[],"fix":{"en":"Fair topics, but keep them for the offer. Now ask about the work: \"What would I do in my first month?\"","tr":"Haklı konular, ama onları teklif aşamasına sakla. Şimdi işi sor: \"What would I do in my first month?\"","fa":"موضوع‌های به‌جایی‌اند، ولی آن‌ها را برای مرحله‌ی پیشنهاد نگه دار. الان درباره‌ی کار بپرس: «What would I do in my first month?»"}},{"by":"AI tool","answer":"Can you tell me more about your company culture and what makes this organisation such a great place to work?","present":[],"fix":{"en":"A question from a list, and it would fit any company. Start with something you read about them.","tr":"Listeden çıkmış bir soru ve her şirkete uyar. Onlarla ilgili okuduğun bir şeyle başla.","fa":"سؤالی از روی فهرست است و از هر شرکتی می‌شود پرسید. با چیزی شروع کن که درباره‌ی خودشان خوانده‌ای."}},{"by":"Engineer","answer":"What does a typical first month look like for a new engineer?","present":["About the real work","Helps me decide"],"fix":{"en":"A good, real question. To make it stronger, add what you read: \"I read that you are building a plant in Konya. Would new engineers work there?\"","tr":"İyi ve gerçek bir soru. Daha güçlü olsun diye okuduğunu ekle: \"I read that you are building a plant in Konya. Would new engineers work there?\"","fa":"سؤال خوب و واقعی است. برای قوی‌تر شدنش چیزی را که خوانده‌ای اضافه کن: «I read that you are building a plant in Konya. Would new engineers work there?»"}},{"by":"Good model","answer":"I read that you are opening a new plant in Konya. What would a new engineer work on there in the first six months?","present":["About the real work","Shows I did research","Helps me decide"],"fix":null}]},"speaking":{"id":"int-7","course":"interview","unit":"int-7","topic":{"en":"Your questions for them","tr":"Onlara soracağın sorular","fa":"سؤال‌های تو از آن‌ها"},"warmup":{"en":"Look at the job ad you are using. Find one thing you want to know more about. No ad yet? Use this one: Customer Support Specialist at an online travel company (two or more years with customers, good written English, weekend shifts; it now sells trips in six new countries).","tr":"Kullandığın iş ilanına bak. Hakkında daha fazla bilgi almak istediğin bir şey bul. Henüz ilanın yok mu? Bunu kullan: Çevrimiçi bir seyahat şirketinde Customer Support Specialist (müşterilerle en az iki yıl deneyim, iyi yazılı İngilizce, hafta sonu vardiyaları; şirket artık altı yeni ülkede seyahat satıyor).","fa":"به آگهی شغلی‌ای که استفاده می‌کنی نگاه کن. یک چیز پیدا کن که می‌خواهی بیشتر درباره‌اش بدانی. هنوز آگهی نداری؟ از این استفاده کن: Customer Support Specialist در یک شرکت سفر اینترنتی (دست‌کم دو سال کار با مشتری، انگلیسی نوشتاری خوب، شیفت آخر هفته؛ این شرکت حالا در شش کشور تازه سفر می‌فروشد)."},"questions":[{"en":"The interviewer asks: \"Do you have any questions for us?\" Ask one question about the work itself.","tr":"Mülakatı yapan kişi soruyor: \"Do you have any questions for us?\" İşin kendisiyle ilgili bir soru sor.","fa":"مصاحبه‌کننده می‌پرسد: «Do you have any questions for us?‎» یک سؤال درباره‌ی خود کار بپرس."},{"en":"Ask one question that shows you did some research (\"I read that... What...?\").","tr":"Araştırma yaptığını gösteren bir soru sor (\"I read that... What...?\").","fa":"یک سؤال بپرس که نشان بدهد تحقیق کرده‌ای («I read that... What...?‎»)."},{"en":"Ask about the next steps.","tr":"Sonraki adımları sor.","fa":"درباره‌ی مراحل بعدی بپرس."},{"en":"After the interview: say your thank-you email in three lines: thanks, one real thing you heard, still interested.","tr":"Mülakattan sonra: teşekkür e-postanı üç satırda söyle: teşekkür, duyduğun gerçek bir şey, hâlâ ilgilendiğin.","fa":"بعد از مصاحبه، ایمیل تشکرت را در سه خط بگو: تشکر، یک چیز واقعی که شنیدی و اینکه هنوز علاقه‌مندی."}],"followups":[{"en":"Ask all three again in 60 seconds, then 45, in this order: the work, the research, the next steps. Then say your three thank-you lines.","tr":"Üçünü de önce 60, sonra 45 saniyede, bu sırayla yeniden sor: iş, araştırma, sonraki adımlar. Sonra üç teşekkür satırını söyle.","fa":"هر سه را دوباره در ۶۰ و بعد ۴۵ ثانیه بپرس، به این ترتیب: کار، تحقیق، مراحل بعدی. بعد سه خط تشکرت را بگو."}],"expressions":[{"phrase":"What does a typical ... look like?","meaning":{"en":"Asks about the real work.","tr":"Gerçek işi sorar.","fa":"درباره‌ی کار واقعی می‌پرسد."}},{"phrase":"I read that... What...?","meaning":{"en":"Shows research, then asks.","tr":"Araştırmanı gösterir, sonra sorar.","fa":"تحقیقت را نشان می‌دهد و بعد می‌پرسد."}},{"phrase":"What are the next steps?","meaning":{"en":"Your last question.","tr":"Soracağın son soru.","fa":"سؤال آخرت."}}],"selfCheck":[{"en":"I asked at least one question about the work or the team.","tr":"İş ya da ekip hakkında en az bir soru sordum.","fa":"دست‌کم یک سؤال درباره‌ی کار یا تیم پرسیدم."},{"en":"One question showed that I had done some research.","tr":"Sorulardan biri araştırma yaptığımı gösterdi.","fa":"یکی از سؤال‌هایم نشان داد که تحقیق کرده‌ام."},{"en":"My helper verbs were in the right place (do / does / is / are).","tr":"Yardımcı fiillerim doğru yerdeydi (do / does / is / are).","fa":"فعل‌های کمکی‌ام سر جایشان بودند (do / does / is / are)."},{"en":"My thank-you lines had one real thing from the conversation.","tr":"Teşekkür satırlarımda görüşmeden gerçek bir şey vardı.","fa":"در خط‌های تشکرم یک چیز واقعی از گفت‌وگو بود."}],"model":"Yes, I have a few. First, what does a typical first week look like for a new team member? I also read that you opened an office in Izmir last year. What are the biggest challenges for that team? And finally, what are the next steps after today? Thank you for meeting me today. I enjoyed hearing about the Izmir office, and I am still very interested."},"writing":{"id":"c-int-7-w","course":"interview","unit":"int-7","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"int-final-4","model":"1. What does a typical first month look like for a new accountant? I want to know what you expect from me early on.\n2. I read that you are moving your reports to a new system. How will that change the work of this team? This shows I did my research.\n3. What are the next steps after today, and when can I expect to hear from you? I need to plan my notice period.","frame":"1. What does a typical ___ look like for ___? I want to know ___.\n2. I read that ___. How will ___? This shows ___.\n3. What are the next steps ___, and when can I ___? I need to ___.","words":[{"word":"typical"},{"word":"I read that"},{"word":"next steps"}],"minWords":60,"minSentences":4,"title":{"en":"Your three questions","tr":"Soracağın üç soru","fa":"سه سؤال تو"},"prompt":{"en":"Write three questions you will ask at the end of an interview for a job you want, with one line under each saying why you want to know (60-90 words in total): one about the work, one that shows research, one about the next steps. No ad yet? Use this one: Customer Support Specialist at an online travel company (two or more years with customers, good written English, weekend shifts; it now sells trips in six new countries).","tr":"İstediğin bir işin mülakatının sonunda soracağın üç soruyu yaz; her birinin altına neden bilmek istediğini anlatan bir satır ekle (toplam 60-90 kelime): biri işle ilgili, biri araştırmanı gösteren, biri sonraki adımlarla ilgili. Henüz ilanın yok mu? Bunu kullan: Çevrimiçi bir seyahat şirketinde Customer Support Specialist (müşterilerle en az iki yıl deneyim, iyi yazılı İngilizce, hafta sonu vardiyaları; şirket artık altı yeni ülkede seyahat satıyor).","fa":"برای کاری که می‌خواهی، سه سؤالی را بنویس که در پایان مصاحبه می‌پرسی، و زیر هرکدام یک خط بنویس که چرا می‌خواهی بدانی (روی هم ۶۰ تا ۹۰ کلمه): یکی درباره‌ی کار، یکی که تحقیقت را نشان بدهد، یکی درباره‌ی مراحل بعدی. هنوز آگهی نداری؟ از این استفاده کن: Customer Support Specialist در یک شرکت سفر اینترنتی (دست‌کم دو سال کار با مشتری، انگلیسی نوشتاری خوب، شیفت آخر هفته؛ این شرکت حالا در شش کشور تازه سفر می‌فروشد)."},"rubric":["Task done: three questions (the work, research, the next steps), each with a reason","Organised: the work first, the next steps last","Language: helper verbs in the right place: What does... / What are...","Tone: curious and professional, not about pay or holidays first"],"rubricI18n":{"tr":["Görev: üç soru (iş, araştırma, sonraki adımlar), her biri bir nedenle","Düzen: önce iş, en sonda sonraki adımlar","Dil: yardımcı fiiller doğru yerde: What does... / What are...","Üslup: meraklı ve profesyonel; önce maaş ya da izin değil"],"fa":["کامل بودن کار: سه سؤال (کار، تحقیق، مراحل بعدی)، هرکدام با یک دلیل","نظم: اول کار، آخر از همه مراحل بعدی","زبان: فعل‌های کمکی سر جایشان: What does... / What are...","لحن: کنجکاو و حرفه‌ای؛ بدون اینکه اول از حقوق یا مرخصی بپرسی"]},"parts":[{"t":{"en":"A question about the work","tr":"İşin kendisiyle ilgili bir soru","fa":"سؤالی درباره‌ی خودِ کار"},"find":["what does a typical","typical","first month","first week","day-to-day","look like"],"sample":"what does a typical first week look like for new support staff?"},{"t":{"en":"A question that shows your research","tr":"Araştırma yaptığını gösteren bir soru","fa":"سؤالی که نشان می‌دهد تحقیق کرده‌ای"},"find":["i read that","i read","i saw","i noticed","on your website"],"sample":"I read you now sell trips in six new countries: which ones first?"},{"t":{"en":"The next steps","tr":"Sonraki adımlar","fa":"قدم‌های بعدی"},"find":["next steps","next step","when can i expect","hear from you"],"sample":"what are the next steps, and when can I expect to hear?"},{"t":{"en":"Why you ask each one","tr":"Her birini neden sorduğun","fa":"چرا هر کدام را می‌پرسی"},"find":["i want to know","this shows","i need to","because"],"sample":"to know what you expect early · to plan my notice period"}]},"exit":{"id":"c-int-7-x","course":"interview","unit":"int-7","type":"exit","items":[{"from":"int-7","kind":"blank","prompt":"How ___ the company train new staff?","options":["does","is","do"],"correct":0,"point":2,"why":{"en":"does: 'the company' is singular, so the question needs does. 'Is' would need -ing, and 'do' is for plural subjects.","tr":"does: 'the company' tekildir, bu yüzden soru does ister. 'Is' -ing ister; 'do' çoğul özneler içindir.","fa":"does درست است، چون the company مفرد است و سؤال does می‌خواهد. is فعل ing‌دار لازم دارد و do برای فاعل جمع است."},"hint2":{"en":"The subject is the company: it, one thing. And train has no -s. Which helper verb carries the -s for it?","tr":"Özne the company, yani tek bir şey (it). train de -s almamış. it için -s'yi hangi yardımcı fiil taşır?","fa":"فاعل ⁨the company⁩ است، یعنی یک چیز (⁨it). train⁩ هم ⁨s⁩ ندارد. کدام فعل کمکی ⁨s⁩ را برای ⁨it⁩ با خودش می‌آورد؟"}},{"from":"int-7","kind":"mcq","prompt":"Which question is best to ask first at the end of an interview?","options":["How much holiday will I get in my first year here?","What would success look like in the first six months?","Do you like your job, and how long have you been here?"],"correct":1,"point":1,"why":{"en":"'What would success look like in the first six months?' is about the real work. Holiday belongs to the offer stage, and asking if they like their job helps you less.","tr":"'What would success look like in the first six months?' gerçek işle ilgilidir. Tatil teklif aşamasına aittir; işini sevip sevmediğini sormak sana daha az yardım eder.","fa":"«What would success look like in the first six months?» درباره‌ی کار واقعی است. مرخصی مال مرحله‌ی پیشنهاد کار است و پرسیدن اینکه کارشان را دوست دارند کمتر کمکت می‌کند."},"hint2":{"en":"Ask first about the work itself, not about what you will get. Which question is about the work?","tr":"Önce alacaklarını değil, işin kendisini sor. Hangi soru işle ilgili?","fa":"اول درباره‌ی خودِ کار بپرس، نه چیزهایی که به دست می‌آوری. کدام سؤال درباره‌ی کار است؟"}},{"from":"int-7","kind":"mcq","prompt":"When should you send a thank-you email after an interview?","options":["Within 24 hours","After two weeks","Only if they offer you the job"],"correct":0,"point":3,"why":{"en":"Within 24 hours: they still remember you and have not decided yet. Two weeks is too late, and waiting for an offer misses the point.","tr":"24 saat içinde: seni hâlâ hatırlarlar ve henüz karar vermemişlerdir. İki hafta çok geç; teklifi beklemek amacı kaçırır.","fa":"ظرف ۲۴ ساعت، چون هنوز یادشان هست و تصمیم نگرفته‌اند. دو هفته خیلی دیر است و منتظر پیشنهاد ماندن هدف را از بین می‌برد."},"hint2":{"en":"Send it while they still remember you, and before they decide. Is that soon or late?","tr":"Seni hâlâ hatırlarken ve karar vermeden önce gönder. Bu erken mi, geç mi?","fa":"وقتی هنوز تو را یادشان هست و قبل از اینکه تصمیم بگیرند بفرست. این یعنی زود یا دیر؟"}},{"from":"int-11","kind":"mcq","prompt":"In a group task, another candidate has a good idea. What do you say?","options":["Building on that, we could test it in one shop.","No, I think my own idea is better than that.","Nothing, so the assessors notice only my ideas."],"correct":0,"point":1,"why":{"en":"'Building on that, we could test it in one shop' adds to their idea and moves the task on. Rejecting it or staying silent looks bad to assessors.","tr":"'Building on that, we could test it in one shop' onların fikrine ekler ve görevi ilerletir. Fikri reddetmek ya da susmak değerlendiricilere kötü görünür.","fa":"«Building on that, we could test it in one shop» ایده‌ی آن‌ها را ادامه می‌دهد و کار را جلو می‌برد. رد کردن ایده یا ساکت ماندن از نگاه ارزیاب‌ها بد است."},"hint2":{"en":"Assessors watch how you treat other people's ideas. Which answer adds to the idea, instead of fighting it or staying silent?","tr":"Değerlendiriciler başkalarının fikirlerine nasıl davrandığını izler. Hangi cevap fikre karşı çıkmak ya da susmak yerine onun üzerine ekliyor?","fa":"ارزیاب‌ها نگاه می‌کنند با ایده‌ی دیگران چطور رفتار می‌کنی. کدام جواب به‌جای مخالفت یا سکوت، چیزی به آن ایده اضافه می‌کند؟"}},{"from":"int-4","kind":"blank","prompt":"Before ___ the call, I always read my notes once.","options":["start","to start","starting"],"correct":2,"point":2,"why":{"en":"starting: 'before' is a preposition here, so the verb takes -ing. 'Start' and 'to start' don't follow before.","tr":"starting: 'before' burada bir edattır, bu yüzden fiil -ing alır. 'Start' ve 'to start' before'dan sonra gelmez.","fa":"starting درست است، چون before اینجا حرف اضافه است و فعل بعدش ing می‌گیرد. start و to start بعد از before نمی‌آیند."}},{"from":"int-1","kind":"blank","prompt":"My sister ___ at a hotel in Dubai for six years, and she is still there.","options":["works","has worked","is working"],"correct":1,"point":2,"why":{"en":"has worked: 'for six years' and 'she is still there' run until now, so use the present perfect. 'Works' and 'is working' don't show the length of time.","tr":"has worked: 'for six years' ve 'she is still there' bugüne kadar sürer, bu yüzden present perfect. 'Works' ve 'is working' süreyi göstermez.","fa":"has worked درست است، چون for six years و she is still there تا الان ادامه دارد و حال کامل می‌خواهد. works و is working مدت را نشان نمی‌دهند."}}]},"explain":{"id":"c-int-7-e","course":"interview","unit":"int-7","type":"explain","level":"B1","title":{"en":"Your questions and a good ending","tr":"Soruların ve iyi bir kapanış","fa":"سؤال‌هایت و یک پایان خوب"},"objective":{"en":"After this lesson, you can ask three good questions, close the interview and send a thank-you email.","tr":"Bu dersin sonunda üç iyi soru sorabilecek, mülakatı kapatabilecek ve teşekkür e-postası gönderebileceksin.","fa":"بعد از این درس می‌توانی سه سؤال خوب بپرسی، مصاحبه را خوب تمام کنی و ایمیل تشکر بفرستی."},"hook":{"en":"\"Any questions for us?\" is your turn, not the end. Good questions show you care about the work, and the answers help you decide if you want the job. So bring three: about the work, from your research, and about the next steps.","tr":"\"Any questions for us?\" son değil, senin sıran demektir. İyi sorular işi önemsediğini gösterir, cevaplar da bu işi isteyip istemediğine karar vermene yardım eder. Bu yüzden üç soruyla gel: işle ilgili, araştırmana dayanan ve sonraki adımlarla ilgili.","fa":"جمله‌ی «Any questions for us?» پایان مصاحبه نیست، نوبت توست. سؤال‌های خوب نشان می‌دهند کار برایت مهم است و جواب‌ها کمکت می‌کنند تصمیم بگیری این کار را می‌خواهی یا نه. پس سه سؤال آماده کن: یکی درباره‌ی کار، یکی بر اساس تحقیق خودت و یکی درباره‌ی مراحل بعدی."},"before":{"en":"Write one question you would ask at the end of an interview.","tr":"Bir mülakatın sonunda soracağın bir soruyu yaz.","fa":"یک سؤال بنویس که آخر مصاحبه می‌پرسی."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"End with three questions","tr":"Üç soruyla bitir","fa":"با سه سؤال تمام کن"},"steps":[{"en":"Bring three, because they may answer one first. Having none can look like low interest.","tr":"Üç soruyla gel, çünkü birini sen sormadan cevaplayabilirler. Hiç sorunun olmaması ilgisizlik gibi görünebilir.","fa":"سه سؤال آماده کن، چون ممکن است یکی را زودتر جواب بدهند. اگر سؤالی نداشته باشی، ممکن است فکر کنند علاقه‌ای نداری.","ex":"Write them down, and take the paper with you."},{"en":"Ask one about the work and one from your research. Both show you want this job.","tr":"Biri iş hakkında, biri araştırmana dayanan soru olsun. İkisi de bu işi istediğini gösterir.","fa":"یکی درباره‌ی کار و یکی بر اساس تحقیق خودت بپرس. هر دو نشان می‌دهند همین کار را می‌خواهی.","ex":"What does a typical first month look like?"},{"en":"Keep holidays and pay rises until they offer you the job. Earlier, they look like your main interest.","tr":"İzin ve zam konularını iş teklif edilene kadar sakla. Daha önce sorarsan asıl ilgin bunlarmış gibi görünür.","fa":"مرخصی و افزایش حقوق را برای وقتی نگه دار که کار را به تو پیشنهاد کردند. اگر زودتر بپرسی، انگار فقط به همین‌ها علاقه داری.","ex":"Not now: How much holiday will I get?"},{"en":"Last, ask about the next steps, so you know when to follow up.","tr":"Son olarak sonraki adımları sor; böylece ne zaman yeniden yazacağını bilirsin.","fa":"آخر از همه درباره‌ی مراحل بعدی بپرس تا بدانی کی پیگیری کنی.","ex":"What are the next steps, and when can I expect to hear?"}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Asking good questions: do, does, is, are","tr":"İyi sorular sormak: do, does, is, are","fa":"سؤال خوب پرسیدن: do، does، is، are"},"steps":[{"en":"Most verbs: question word + do / does + subject + verb.","tr":"Çoğu fiil: soru kelimesi + do / does + özne + fiil.","fa":"برای بیشتر فعل‌ها اول کلمه‌ی پرسشی می‌آید، بعد do یا does، بعد فاعل و بعد فعل.","ex":"What do new staff do in the first week?"},{"en":"After does, the verb has no -s, because does already has it.","tr":"does kelimesinden sonra fiil -s almaz, çünkü -s zaten does içinde vardır.","fa":"بعد از does فعل ‎-s نمی‌گیرد، چون خود does آن را دارد.","ex":"How does the team measure success?"},{"en":"With be, there is no do or does: is or are comes first.","tr":"be ile do ya da does kullanılmaz: is ya da are başa gelir.","fa":"با be دیگر do یا does نمی‌آید: is یا are اول می‌آید.","ex":"What are the next steps?"}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["What / How + do + I / you / they + verb","What do new staff do in the first week?"],["What / How + does + he / she / it + verb (no -s)","How does the team measure success?"],["With be: is / are first","What are the next steps?"]]},"tip":{"en":"Turkish asks with -mı or a question word and Persian with tone or 'آیا', and the word order stays the same. English needs a helper verb in front: do, does, is, are.","tr":"Türkçede soru '-mı' ekiyle ya da soru kelimesiyle kurulur ve sıra değişmez. İngilizcede öne bir yardımcı fiil gelir: do, does, is, are.","fa":"در فارسی سؤال را با لحن یا «آیا» می‌سازیم و ترتیب کلمه‌ها عوض نمی‌شود. انگلیسی یک فعل کمکی جلوی جمله می‌خواهد: do، does، is، are."},"wrong":"What the next steps are after today?","right":"What are the next steps after today?"},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"The thank-you email","tr":"Teşekkür e-postası","fa":"ایمیل تشکر"},"body":{"en":"Send it within 24 hours, while they still remember you: thank them, mention one real thing from the conversation, and say you are still interested. If the date they gave you passes, send one short, polite message.","tr":"Seni henüz hatırlarken, 24 saat içinde gönder: teşekkür et, görüşmeden gerçek bir şeyi an ve hâlâ ilgilendiğini söyle. Sana söyledikleri tarih geçerse haber sormak için kısa ve kibar bir mesaj gönder.","fa":"آن را ظرف ۲۴ ساعت بفرست که هنوز تو را به یاد دارند. تشکر کن، یک چیز واقعی از گفت‌وگو را یادآوری کن و بگو هنوز علاقه‌مندی. اگر تاریخی که گفته بودند گذشت، یک پیام کوتاه و مؤدبانه بفرست و خبر بپرس."},"phrases":[{"phrase":"What does a typical ... look like?","meaning":{"en":"Asks about the real work.","tr":"Gerçek işi sorar.","fa":"درباره‌ی کار واقعی می‌پرسد."}},{"phrase":"I read that... What...?","meaning":{"en":"Shows research, then asks.","tr":"Araştırmanı gösterir, sonra sorar.","fa":"تحقیقت را نشان می‌دهد و بعد می‌پرسد."}},{"phrase":"What are the next steps?","meaning":{"en":"Your last question.","tr":"Soracağın son soru.","fa":"سؤال آخرت."}},{"phrase":"look forward to","meaning":{"en":"To feel happy about something that will happen.","tr":"dört gözle beklemek.","fa":"مشتاقانه منتظرِ چیزی بودن"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Ask about the work","tr":"İşi sor","fa":"درباره‌ی کار بپرس"},"item":"Weak: How much holiday do I get? Is there a pay rise after six months? Your facts: you read that they are moving reports to a new system.","answer":"I read that you are moving your reports to a new system. How will that change the work of this team?","walk":[{"en":"These questions are about what you get. Keep them for later.","tr":"Bu sorular senin ne alacağınla ilgili. Sonraya sakla.","fa":"این سؤال‌ها درباره‌ی چیزهایی است که خودت می‌گیری. برای بعد نگهشان دار."},{"en":"Start with a fact you found. It shows your research.","tr":"Bulduğun bir gerçekle başla, çünkü bu araştırma yaptığını gösterir.","fa":"با واقعیتی که پیدا کرده‌ای شروع کن، چون نشان می‌دهد تحقیق کرده‌ای."},{"en":"Ask how it changes the real work.","tr":"Bunun gerçek işi nasıl değiştirdiğini sor.","fa":"بپرس این واقعیت در عمل چه چیزی را در کار عوض می‌کند."}],"cut":["How much holiday","a pay rise after six months"],"cutHint":{"en":"Tap what is about what you get, not the work.","tr":"İşle değil, senin ne alacağınla ilgili kısımlara dokun.","fa":"روی چیزهایی بزن که درباره‌ی چیزی است که تو به دست می‌آوری، نه درباره‌ی کار."}},"quick":{"prompt":"Your last question at the end of the interview should be about ___.","options":["the next steps","your holidays","the interviewer's own career"],"correct":0,"why":{"en":"the next steps: then you know when to expect news and when to follow up.","tr":"the next steps: böylece ne zaman haber bekleyeceğini ve ne zaman tekrar yazacağını bilirsin.","fa":"جواب ⁨the next steps⁩ است، چون این‌طوری می‌دانی کی منتظر خبر باشی و کی پیگیری کنی."},"hint2":{"en":"After you leave, you want to know when to expect news and when to write. Which question tells you that?","tr":"Çıktıktan sonra ne zaman haber bekleyeceğini ve ne zaman yazacağını bilmek istersin. Bunu sana hangi soru söyler?","fa":"بعد از اینکه بیرون آمدی، می‌خواهی بدانی کی منتظر خبر باشی و کی پیگیری کنی. کدام سؤال این را به تو می‌گوید؟"}},"remember":{"en":"Your questions are the last thing they hear. Make them about the work. You can now end an interview with three good questions and write a thank-you email. Next, you write your own questions, each with its reason.","tr":"Soruların duydukları son şeydir. İşle ilgili olsunlar. Artık bir mülakatı üç iyi soruyla bitirebilir ve teşekkür e-postası yazabilirsin. Sırada kendi sorularını, her birinin nedeniyle birlikte yazmak var.","fa":"سؤال‌هایت آخرین چیزی است که از تو می‌شنوند، پس درباره‌ی کار باشند. حالا می‌توانی مصاحبه را با سه سؤال خوب تمام کنی و ایمیل تشکر بنویسی. در ادامه سؤال‌های خودت را همراه با دلیل هر کدام می‌نویسی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Softer questions: indirect questions","tr":"Daha yumuşak sorular: dolaylı sorular","fa":"سؤال‌های نرم‌تر: سؤال غیرمستقیم"},"steps":[{"en":"A polite opener, then statement order.","tr":"Kibar bir giriş, sonra düz cümle sırası.","fa":"با یک عبارت مؤدبانه شروع کن و بعد ترتیب جمله‌ی خبری بیاور.","ex":"Could you tell me what the next steps are?"},{"en":"No do or does after the opener.","tr":"Girişten sonra do ya da does yok.","fa":"بعد از این عبارت مؤدبانه do یا does نمی‌آید.","ex":"I was wondering how the team measures success."},{"en":"Mix one or two with direct questions.","tr":"Bir ikisini doğrudan sorularla karıştır.","fa":"یکی دو سؤال این‌طوری را کنار سؤال‌های مستقیم بپرس.","ex":"What does the first week look like?"}],"table":{"headers":{"en":["Direct","Indirect"],"tr":["Doğrudan","Dolaylı"],"fa":["مستقیم","غیرمستقیم"]},"rows":[["What are the next steps?","Could you tell me what the next steps are?"],["How does the team measure success?","I was wondering how the team measures success."],["When does the training start?","Do you know when the training starts?"]]},"body":{"en":"B2: make one of your three questions indirect (Could you tell me... / I was wondering...).","tr":"B2: üç sorundan birini dolaylı yap (Could you tell me... / I was wondering...).","fa":"در مسیر B2: یکی از سه سؤالت را غیرمستقیم کن (Could you tell me... / I was wondering...)."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
